def test_mgga_xc_tpsslyp1w_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_xc_tpsslyp1w", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.793487511086238e+00, -4.697801699979242e+00, -4.563677903053071e+00, -4.377794571721059e+00, -4.124338586036656e+00, -3.786733384966811e+00, -3.351934276110491e+00, -2.818915427943710e+00, -2.213487838330388e+00, -1.606273354913032e+00, -1.067789730971806e+00, -7.320387264216238e-01, -6.406956598838875e-01, -5.458372701070082e-01, -3.905108300183500e-01, -2.404006343345225e-01, -1.317943456577141e-01, -5.218516560594530e-02, -1.145964622900726e-02, -1.300720299809417e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


